-- Starter attire catalog (docs/attire-affiliates.md): 40 real products read
-- on the retailers' own pages on 2026-10-22. Plain product links, no photos
-- (no image rights yet), prices dated. Revelry and The Black Tux are missing
-- only because their pages blocked automated reads; add them by hand.
--
-- Safe to re-run: retailers match on name, items on retailer_url.

insert into attire_merchants (name, website, network, status, commission_note)
select 'Azazie', 'https://www.azazie.com', null, 'Not applied', '10%, 90-day cookie (unverified, per docs/attire-affiliates.md)'
where not exists (select 1 from attire_merchants where name = 'Azazie');

insert into attire_merchants (name, website, network, status, commission_note)
select 'Generation Tux', 'https://generationtux.com', null, 'Not applied', 'Planner referral program; affiliate listing unverified'
where not exists (select 1 from attire_merchants where name = 'Generation Tux');

insert into attire_merchants (name, website, network, status, commission_note)
select 'Brilliant Earth', 'https://www.brilliantearth.com', 'Impact', 'Not applied', '5% bridal, 7% fine jewelry, 30 days, $500 cap per order'
where not exists (select 1 from attire_merchants where name = 'Brilliant Earth');

insert into attire_items (
